"use client";

import { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import { showToast } from "@/components/ToastNotification";
import {
  Box,
  IconButton,
  Paper,
  Typography,
  TextField,
  InputAdornment,
  Tooltip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
  Button,
  Skeleton,
} from "@mui/material";
import {
  Close,
  Send,
  DeleteOutline,
  AutoAwesome
} from "@mui/icons-material";
import { getChatHistoryAction, saveChatMessageAction, clearChatHistoryAction, generateGeminiResponseAction } from "@/features/chat/actions";
import { getAccountsAction } from "@/features/account/actions";
import { getEnumsAction } from "@/features/enum/actions";
import { getIncomeListAction } from "@/features/income/actions";
import { getOutcomeListAction } from "@/features/outcome/actions";
import { getTransferListAction } from "@/features/transfer/actions";
import { getLedgerListAction } from "@/features/ledger/actions";
import { getTradesAction } from "@/features/investment/actions";
import { getLatestRatesAction } from "@/features/exchange/actions";
import { getSystemInstruction } from "../constants/systemInstruction";
import { executeAgenticActions } from "../utils/actionExecutor";

type Message = {
  role: "user" | "model";
  text: string;
};

export default function AIChatbot() {
  const router = useRouter();
  const [isOpen, setIsOpen] = useState(false);
  const [isOpening, setIsOpening] = useState(false);
  const [mounted, setMounted] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    {
      role: "model",
      text: "Halo! Saya **Finter AI**, asisten keuangan pribadi cerdas Anda. Ada yang bisa saya bantu untuk mengelola, menganalisis, atau memberikan saran mengenai anggaran keuangan Anda hari ini? 💼✨",
    },
  ]);
  const [loading, setLoading] = useState(false);
  const [streamingText, setStreamingText] = useState("");
  const [width, setWidth] = useState(380);
  const [isResizing, setIsResizing] = useState(false);
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const snapTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const [pos, setPos] = useState<{
    left: number | null;
    top: number | null;
    right: number | null;
    bottom: number | null;
  } | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragRef = useRef<{ startX: number; startY: number; offsetX: number; offsetY: number } | null>(null);
  const dragTotalMovement = useRef(0);

  const getAbsoluteCoords = (
    p: { left: number | null; top: number | null; right: number | null; bottom: number | null } | null
  ) => {
    const btnSize = 48;
    const w = typeof window !== "undefined" ? window.innerWidth : 1000;
    const h = typeof window !== "undefined" ? window.innerHeight : 1000;
    if (!p) {
      return { x: w - btnSize - 24, y: h - btnSize - 24 };
    }
    let x = 0;
    let y = 0;
    if (p.left !== null) {
      x = p.left;
    } else if (p.right !== null) {
      x = w - btnSize - p.right;
    } else {
      x = w - btnSize - 24;
    }

    if (p.top !== null) {
      y = p.top;
    } else if (p.bottom !== null) {
      y = h - btnSize - p.bottom;
    } else {
      y = h - btnSize - 24;
    }
    return { x, y };
  };

  const startResize = (mouseDownEvent: React.MouseEvent) => {
    mouseDownEvent.preventDefault();
    setIsResizing(true);
    const startX = mouseDownEvent.clientX;
    const startWidth = width;
    const absCoords = getAbsoluteCoords(pos);
    const isLeftAnchored = absCoords.x < window.innerWidth / 2;

    const handleMouseMove = (mouseMoveEvent: MouseEvent) => {
      const deltaX = mouseMoveEvent.clientX - startX;
      const newWidth = isLeftAnchored ? startWidth + deltaX : startWidth - deltaX;
      const clampedWidth = Math.max(340, Math.min(700, newWidth));
      setWidth(clampedWidth);
    };

    const handleMouseUp = () => {
      setIsResizing(false);
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);
  };

  const handlePointerDown = (e: React.PointerEvent) => {
    if (snapTimeoutRef.current) {
      clearTimeout(snapTimeoutRef.current);
      snapTimeoutRef.current = null;
    }
    e.currentTarget.setPointerCapture(e.pointerId);
    setIsDragging(true);
    dragTotalMovement.current = 0;
    const coords = getAbsoluteCoords(pos);
    dragRef.current = { startX: e.clientX, startY: e.clientY, offsetX: coords.x, offsetY: coords.y };
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDragging || !dragRef.current) return;
    const deltaX = e.clientX - dragRef.current.startX;
    const deltaY = e.clientY - dragRef.current.startY;
    dragTotalMovement.current += Math.abs(deltaX) + Math.abs(deltaY);
    
    const nextLeft = dragRef.current.offsetX + deltaX;
    const nextTop = dragRef.current.offsetY + deltaY;

    if (pos && pos.left === nextLeft && pos.top === nextTop) {
      return;
    }

    setPos({
      left: nextLeft,
      top: nextTop,
      right: null,
      bottom: null,
    });
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (!isDragging) return;
    setIsDragging(false);
    e.currentTarget.releasePointerCapture(e.pointerId);

    if (dragTotalMovement.current < 10) {
      setIsOpen((prev) => {
        const willOpen = !prev;
        if (willOpen) {
          setIsOpening(true);
          setTimeout(() => setIsOpening(false), 400);
        }
        return willOpen;
      });
    } else {
      if (!pos) return;
      const currentX = pos.left !== null ? pos.left : 0;
      const currentY = pos.top !== null ? pos.top : 0;

      const btnSize = 48;
      const padding = 20;
      const w = window.innerWidth;
      const h = window.innerHeight;

      const distLeft = currentX;
      const distRight = w - (currentX + btnSize);
      const distTop = currentY;
      const distBottom = h - (currentY + btnSize);

      const min = Math.min(distLeft, distRight, distTop, distBottom);

      let finalLeft: number | null = null;
      let finalTop: number | null = null;
      let finalRight: number | null = null;
      let finalBottom: number | null = null;

      if (min === distLeft) {
        finalLeft = padding;
      } else if (min === distRight) {
        finalRight = padding;
      } else {
        if (currentX < w / 2) {
          finalLeft = currentX;
        } else {
          finalRight = w - btnSize - currentX;
        }
      }

      if (min === distTop) {
        finalTop = padding;
      } else if (min === distBottom) {
        finalBottom = padding;
      } else {
        if (currentY < h / 2) {
          finalTop = currentY;
        } else {
          finalBottom = h - btnSize - currentY;
        }
      }

      if (finalLeft !== null) {
        finalLeft = Math.max(padding, Math.min(w - btnSize - padding, finalLeft));
      }
      if (finalRight !== null) {
        finalRight = Math.max(padding, Math.min(w - btnSize - padding, finalRight));
      }
      if (finalTop !== null) {
        finalTop = Math.max(padding, Math.min(h - btnSize - padding, finalTop));
      }
      if (finalBottom !== null) {
        finalBottom = Math.max(padding, Math.min(h - btnSize - padding, finalBottom));
      }

      const targetLeft = finalLeft !== null ? finalLeft : w - btnSize - finalRight!;
      const targetTop = finalTop !== null ? finalTop : h - btnSize - finalBottom!;

      setPos({
        left: targetLeft,
        top: targetTop,
        right: null,
        bottom: null,
      });

      snapTimeoutRef.current = setTimeout(() => {
        setPos({
          left: finalLeft,
          top: finalTop,
          right: finalRight,
          bottom: finalBottom,
        });
        snapTimeoutRef.current = null;
      }, 400);
    }
    dragRef.current = null;
  };

  const [confirmOpen, setConfirmOpen] = useState(false);

  useEffect(() => {
    setMounted(true);

    const loadChatHistory = async () => {
      try {
        const res = await getChatHistoryAction();
        if (res && res.success && Array.isArray(res.data) && res.data.length > 0) {
          setMessages(res.data.map((m: any) => ({ role: m.role, text: m.text })));
        }
      } catch (err) {
        console.error("Gagal memuat riwayat chat:", err);
      }
    };
    loadChatHistory();

    const handleResize = () => {
      setPos((prev) => {
        if (!prev) return null;
        const btnSize = 48;
        const padding = 20;
        const w = window.innerWidth;
        const h = window.innerHeight;

        let { left, top, right, bottom } = prev;

        if (left !== null) {
          left = Math.max(padding, Math.min(w - btnSize - padding, left));
        }
        if (right !== null) {
          right = Math.max(padding, Math.min(w - btnSize - padding, right));
        }
        if (top !== null) {
          top = Math.max(padding, Math.min(h - btnSize - padding, top));
        }
        if (bottom !== null) {
          bottom = Math.max(padding, Math.min(h - btnSize - padding, bottom));
        }

        return { left, top, right, bottom };
      });
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    if (isOpen && !isOpening && scrollRef.current) {
      const timer = setTimeout(() => {
        if (scrollRef.current) {
          scrollRef.current.scrollTo({
            top: scrollRef.current.scrollHeight,
            behavior: "auto",
          });
        }
      }, 50);
      return () => clearTimeout(timer);
    }
  }, [isOpening, isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: "smooth",
      });
    }
  }, [messages, loading, streamingText]);

  const parseCleanFloat = (val: string | undefined): number => {
    if (!val) return 0;
    const lower = val.toLowerCase().trim();
    let multiplier = 1;
    if (lower.includes("rb") || lower.includes("ribu") || lower.endsWith("k")) {
      multiplier = 1000;
    } else if (lower.includes("jt") || lower.includes("juta")) {
      multiplier = 1000000;
    }

    const cleaned = lower.replace(/[^0-9]/g, "");
    const parsed = parseFloat(cleaned || "0");
    if (multiplier > 1 && parsed < 1000) {
      return parsed * multiplier;
    }
    return parsed;
  };

  if (!mounted) return null;

  const handleSend = async (textToSend: string) => {
    const prompt = textToSend.trim();
    if (!prompt || loading) return;

    const newMessages: Message[] = [...messages, { role: "user", text: prompt }];
    setMessages(newMessages);
    setLoading(true);
    saveChatMessageAction("user", prompt).catch((err) => console.error("Gagal menyimpan pesan user:", err));

    try {
      const [accs, types, sources, cats, subcats, incs, outs, txs, savings, trades, rates] = await Promise.all([
        getAccountsAction(),
        getEnumsAction('income_type'),
        getEnumsAction('income_source'),
        getEnumsAction('outcome_category'),
        getEnumsAction('outcome_subcategory'),
        getIncomeListAction({ pageSize: 15 }),
        getOutcomeListAction({ pageSize: 15 }),
        getTransferListAction({ pageSize: 15 }),
        getLedgerListAction({ pageSize: 15 }),
        getTradesAction(),
        getLatestRatesAction(),
      ]);

      const getAccountCurrency = (accId: number) => {
        if (accs.success && Array.isArray(accs.data)) {
          const acc = accs.data.find((a: any) => a.id === accId);
          return acc ? acc.currency : "IDR";
        }
        return "IDR";
      };

      const formatAmount = (amount: number, accId: number) => {
        const currency = getAccountCurrency(accId);
        if (currency === "USD") {
          return `$${amount.toLocaleString("en-US")}`;
        }
        return `Rp ${amount.toLocaleString("id-ID")}`;
      };

      let metadataContext = "\n\nDATA SISTEM AKTIF SAAT INI (Gunakan ID numerik asli ini dalam atribut tag aksi):\n";
      if (accs.success && Array.isArray(accs.data)) {
        metadataContext += "Akun (accountId):\n" + accs.data.map((a: any) => `- ID: "${a.id}", Nama: "${a.name}", Bucket: "${a.bucket}"`).join("\n") + "\n";
      }
      if (types.success && Array.isArray(types.data)) {
        metadataContext += "Jenis Pemasukan (typeId):\n" + types.data.map((t: any) => `- ID: "${t.id}", Nilai: "${t.value}"`).join("\n") + "\n";
      }
      if (sources.success && Array.isArray(sources.data)) {
        metadataContext += "Sumber Pemasukan (sourceId):\n" + sources.data.map((s: any) => `- ID: "${s.id}", Nilai: "${s.value}"`).join("\n") + "\n";
      }
      if (cats.success && Array.isArray(cats.data)) {
        metadataContext += "Kategori Pengeluaran (categoryId):\n" + cats.data.map((c: any) => `- ID: "${c.id}", Nilai: "${c.value}"`).join("\n") + "\n";
      }
      if (subcats.success && Array.isArray(subcats.data)) {
        metadataContext += "Subkategori Pengeluaran (subcategoryId, parentId merujuk ke categoryId):\n" + subcats.data.map((s: any) => `- ID: "${s.id}", Nilai: "${s.value}", parentId: "${s.parentId}"`).join("\n") + "\n";
      }
      if (incs.success && incs.data && Array.isArray(incs.data.items)) {
        metadataContext += "Recent 15 Incomes (id untuk edit-income):\n" + incs.data.items.map((i: any) => `- ID: "${i.id}", Nominal: "${i.amount}", Catatan: "${i.note || ''}", Tanggal: "${i.date}"`).join("\n") + "\n";
      }
      if (outs.success && outs.data && Array.isArray(outs.data.items)) {
        metadataContext += "Recent 15 Outcomes (id untuk edit-outcome):\n" + outs.data.items.map((o: any) => `- ID: "${o.id}", Nominal: "${o.amount}", Catatan: "${o.note || ''}", Tanggal: "${o.date}"`).join("\n") + "\n";
      }
      if (txs.success && txs.data && Array.isArray(txs.data.items)) {
        metadataContext += "Recent 15 Transfers (id untuk edit-transfer):\n" + txs.data.items.map((t: any) => `- ID: "${t.id}", Nominal: "${t.amount}", Dari: "${t.fromAccountId}", Ke: "${t.toAccountId}", Catatan: "${t.note || ''}", Tanggal: "${t.date}"`).join("\n") + "\n";
      }
      if (savings.success && Array.isArray(savings.data)) {
        metadataContext += "Recent 15 Savings Ledger Entries:\n" + savings.data.map((s: any) => `- ID: "${s.id}", Nominal: "${s.amount}", Jenis: "${s.direction}", Catatan: "${s.note || ''}", Tanggal: "${s.date}"`).join("\n") + "\n";
      }
      if (trades.success && Array.isArray(trades.data)) {
        metadataContext += "Recent Investment Trades:\n" + trades.data.map((t: any) => `- ID: "${t.id}", Simbol: "${t.asset}", Tipe: "${t.type}", Jumlah: "${t.jumlahAwal}", Total Nilai: "${t.jumlahAkhir}", Catatan: "${t.catatan || ''}"`).join("\n") + "\n";
      }
      if (rates.success && Array.isArray(rates.data)) {
        metadataContext += "Live Currency Exchange Rates (Base USD):\n" + rates.data.map((r: any) => {
          const valStr = r.rate != null ? Number(r.rate).toFixed(4) : 'N/A';
          return `- ${r.code} (${r.symbol || ''}): Rate ${valStr} terhadap 1 USD`;
        }).join("\n") + "\n";
      }

      const formattedContents = newMessages.map((m) => ({
        role: m.role,
        parts: [{ text: m.text }],
      }));

      const localDateStr = new Date().toISOString().split('T')[0];
      const systemInstruction = {
        parts: [{ text: getSystemInstruction(metadataContext, localDateStr) }],
      };

      let resultText = "";
      let success = false;
      
      const resAction = await generateGeminiResponseAction(formattedContents, systemInstruction);
      if (resAction && resAction.success && typeof resAction.data === "string") {
        resultText = resAction.data;
        success = true;
      }
      
      if (!success) {
        resultText = "⚠️ **Semua layanan asisten AI sedang sibuk.** Silakan coba lagi beberapa saat lagi.";
      }

      setLoading(false);

      const actionRegex = /<action\s+([^>]+)\s*\/>/gi;
      const actionMatches = [...resultText.matchAll(actionRegex)];
      const parsedActions: any[] = [];

      for (const match of actionMatches) {
        const attrs: Record<string, string> = {};
        const attrString = match[1];
        const attrRegex = /(\w+)="([^"]+)"/g;
        let attrMatch;
        while ((attrMatch = attrRegex.exec(attrString)) !== null) {
          attrs[attrMatch[1]] = attrMatch[2];
        }
        parsedActions.push(attrs);
      }

      const cleanedText = resultText
        .replace(actionRegex, "")
        .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "[Script Terblokir]")
        .replace(/<[^>]+>/g, "")
        .replace(/```[\s\S]*?```/g, "[Blok kode tidak diperbolehkan]")
        .trim();

      let currentWordIndex = 0;
      const words = cleanedText.split(" ");
      setStreamingText("");

      const timer = setInterval(() => {
        if (currentWordIndex < words.length) {
          setStreamingText((prev) => prev + (prev ? " " : "") + words[currentWordIndex]);
          currentWordIndex++;
        } else {
          clearInterval(timer);
          setStreamingText("");
          setMessages((prev) => [...prev, { role: "model", text: cleanedText }]);
          saveChatMessageAction("model", cleanedText).catch((err) => console.error("Gagal menyimpan pesan model:", err));

          if (parsedActions.length > 0) {
            setTimeout(async () => {
              await executeAgenticActions(parsedActions, router, formatAmount, parseCleanFloat);
            }, 1200);
          }
        }
      }, 35);
    } catch (err) {
      console.error(err);
      setMessages((prev) => [
        ...prev,
        {
          role: "model",
          text: "🛑 **Terjadi kesalahan teknis.** Silakan periksa koneksi internet Anda atau coba lagi nanti.",
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  const handleClearClick = () => {
    setConfirmOpen(true);
  };

  const handleConfirmClear = async () => {
    setConfirmOpen(false);
    try {
      await clearChatHistoryAction();
      setMessages([
        {
          role: "model",
          text: "Halo kembali! Percakapan telah dibersihkan. Ada yang bisa **Finter AI** bantu lagi dalam perencanaan keuangan Anda? 📊💰",
        },
      ]);
      showToast("Percakapan berhasil dibersihkan!", "success");
    } catch (err) {
      console.error("Gagal membersihkan riwayat chat:", err);
      showToast("Gagal membersihkan riwayat chat", "error");
    }
  };

  const renderMarkdown = (text: string) => {
    const lines = text.split("\n");
    return lines.map((line, lineIdx) => {
      const indentMatch = line.match(/^(\s*)/);
      const indentCount = indentMatch ? indentMatch[0].length : 0;
      const trimmed = line.trim();
      const depth = Math.max(0, Math.floor(indentCount / 2));

      if (trimmed === "---") {
        return (
          <Box
            key={lineIdx}
            sx={{
              borderBottom: "1px solid rgba(255, 255, 255, 0.08)",
              my: 1.5,
              width: "100%",
            }}
          />
        );
      }

      if (trimmed.startsWith("### ")) {
        return (
          <Typography
            key={lineIdx}
            sx={{
              fontSize: "0.9375rem",
              fontWeight: 700,
              color: "#818cf8",
              mt: 1.5,
              mb: 0.75,
              lineHeight: 1.3,
              pl: depth > 0 ? depth * 2 : 0,
            }}
          >
            {parseInlineMarkdown(trimmed.substring(4))}
          </Typography>
        );
      }

      if (trimmed.startsWith("## ")) {
        return (
          <Typography
            key={lineIdx}
            sx={{
              fontSize: "1rem",
              fontWeight: 700,
              color: "#818cf8",
              mt: 1.75,
              mb: 1,
              lineHeight: 1.3,
              pl: depth > 0 ? depth * 2 : 0,
            }}
          >
            {parseInlineMarkdown(trimmed.substring(3))}
          </Typography>
        );
      }

      if (trimmed.startsWith("# ")) {
        return (
          <Typography
            key={lineIdx}
            sx={{
              fontSize: "1.0625rem",
              fontWeight: 800,
              color: "#ffffff",
              mt: 2,
              mb: 1,
              lineHeight: 1.3,
            }}
          >
            {parseInlineMarkdown(trimmed.substring(2))}
          </Typography>
        );
      }

      if (trimmed.startsWith("- ") || trimmed.startsWith("* ")) {
        const listContent = trimmed.substring(2);
        return (
          <Box
            key={lineIdx}
            sx={{
              display: "flex",
              alignItems: "flex-start",
              gap: 1,
              pl: 1 + (depth * 1.25),
              mt: depth === 0 ? 1.25 : 0.25,
              mb: 0.25,
            }}
          >
            <Typography sx={{ color: depth > 0 ? "#64748b" : "#818cf8", fontSize: "0.8125rem", lineHeight: 1.5 }}>
              {depth > 0 ? "◦" : "•"}
            </Typography>
            <Typography sx={{ fontSize: "0.8125rem", lineHeight: 1.5, color: "#cbd5e1" }}>
              {parseInlineMarkdown(listContent)}
            </Typography>
          </Box>
        );
      }

      const numListMatch = trimmed.match(/^(\d+)\.\s(.*)/);
      if (numListMatch) {
        const num = numListMatch[1];
        const listContent = numListMatch[2];
        return (
          <Box
            key={lineIdx}
            sx={{
              display: "flex",
              alignItems: "flex-start",
              gap: 1,
              pl: 1 + (depth * 1.25),
              mt: depth === 0 ? 1.25 : 0.25,
              mb: 0.25,
            }}
          >
            <Typography sx={{ color: "#818cf8", fontSize: "0.8125rem", fontWeight: 600, lineHeight: 1.5 }}>
              {num}.
            </Typography>
            <Typography sx={{ fontSize: "0.8125rem", lineHeight: 1.5, color: "#cbd5e1" }}>
              {parseInlineMarkdown(listContent)}
            </Typography>
          </Box>
        );
      }

      return (
        <Typography
          key={lineIdx}
          sx={{
            fontSize: "0.8125rem",
            lineHeight: 1.5,
            color: "#cbd5e1",
            minHeight: trimmed === "" ? "0.5rem" : "auto",
            mb: lineIdx === lines.length - 1 ? 0 : 0.75,
          }}
        >
          {parseInlineMarkdown(line)}
        </Typography>
      );
    });
  };

  const parseInlineMarkdown = (text: string) => {
    const boldParts = text.split(/(\*\*.*?\*\*)/g);

    return boldParts.flatMap((boldPart, bIdx) => {
      let segmentContent: string = boldPart;
      let isBold = false;

      if (boldPart.startsWith("**") && boldPart.endsWith("**")) {
        segmentContent = boldPart.substring(2, boldPart.length - 2);
        isBold = true;
      }

      const italicParts = segmentContent.split(/(\*.*?\*)/g);
      const innerProcessed = italicParts.map((italicPart, iIdx) => {
        if (italicPart.startsWith("*") && italicPart.endsWith("*")) {
          return (
            <em key={`i-${bIdx}-${iIdx}`} style={{ fontStyle: "italic", fontWeight: 500, color: "#e2e8f0", paddingRight: "2px" }}>
              {italicPart.substring(1, italicPart.length - 1)}
            </em>
          );
        }
        return italicPart;
      });

      if (isBold) {
        return (
          <strong key={`b-${bIdx}`} style={{ fontWeight: 700, color: "#ffffff" }}>
            {innerProcessed}
          </strong>
        );
      }
      return innerProcessed;
    });
  };

  const fabLeft = pos && pos.left !== null ? pos.left : "auto";
  const fabTop = pos && pos.top !== null ? pos.top : "auto";
  const fabRight = pos && pos.right !== null ? pos.right : (pos ? "auto" : 24);
  const fabBottom = pos && pos.bottom !== null ? pos.bottom : (pos ? "auto" : 24);

  const absCoords = getAbsoluteCoords(pos);
  const isLeftAnchored = absCoords.x < (typeof window !== "undefined" ? window.innerWidth : 1000) / 2;
  const chatWindowTop = absCoords.y < 600 ? absCoords.y + 64 : "auto";
  const chatWindowBottom = absCoords.y >= 600 ? (typeof window !== "undefined" ? window.innerHeight : 1000) - absCoords.y + 16 : 96;
  const chatWindowLeft = isLeftAnchored ? absCoords.x : "auto";
  const chatWindowRight = isLeftAnchored ? "auto" : (typeof window !== "undefined" ? window.innerWidth : 1000) - (absCoords.x + 48);

  return (
    <>
      {/* Pulse/Glow Trigger Button*/}
      <Box
        id="tour-ai-chatbot-btn"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        sx={{
          position: "fixed",
          left: fabLeft,
          top: fabTop,
          right: fabRight,
          bottom: fabBottom,
          zIndex: 1000,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          touchAction: "none",
          cursor: isDragging ? "grabbing" : "grab",
          transition: isDragging ? "none" : "all 0.4s cubic-bezier(0.19, 1, 0.22, 1)",
        }}
      >
        {!isOpen && (
          <Box
            sx={{
              position: "absolute",
              width: 48,
              height: 48,
              borderRadius: "50%",
              backgroundColor: "rgba(99,102,241,0.25)",
              animation: "ping 2s cubic-bezier(0, 0, 0.2, 1) infinite",
              "@keyframes ping": {
                "75%, 100%": {
                  transform: "scale(1.6)",
                  opacity: 0,
                },
              },
            }}
          />
        )}

        <IconButton
          disableRipple
          sx={{
            width: 48,
            height: 48,
            borderRadius: "50%",
            background: isOpen
              ? "linear-gradient(135deg, #6366f1 0%, #4f46e5 100%)"
              : "linear-gradient(135deg, rgba(99,102,241,0.55) 0%, rgba(79,70,229,0.55) 100%)",
            color: "#ffffff !important",
            boxShadow: isOpen
              ? "0 8px 30px rgba(99, 102, 241, 0.4)"
              : "0 4px 15px rgba(99, 102, 241, 0.15)",
            backdropFilter: "blur(4px)",
            transform: isOpen ? "scale(1)" : "scale(0.88)",
            transition: "all 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
            "& .MuiSvgIcon-root": {
              color: "#ffffff !important",
              opacity: "1 !important",
            },
            "&:hover": {
              transform: "scale(1.1) rotate(15deg)",
              background: "linear-gradient(135deg, #6366f1 0%, #4f46e5 100%)",
              boxShadow: "0 12px 35px rgba(99, 102, 241, 0.6)",
              "& .MuiSvgIcon-root": {
                color: "#ffffff !important",
                opacity: "1 !important",
              },
            },
          }}
        >
          {isOpen ? (
            <Close sx={{ fontSize: 20, color: "#ffffff !important" }} />
          ) : (
            <AutoAwesome sx={{ fontSize: 18, color: "#ffffff !important" }} />
          )}
        </IconButton>
      </Box>

      {/* Floating Chat Window */}
      {isOpen && (
        <Paper
          elevation={24}
          sx={{
            position: "fixed",
            top: chatWindowTop,
            bottom: chatWindowBottom,
            left: { xs: 24, sm: chatWindowLeft },
            right: { xs: 24, sm: chatWindowRight },
            width: { xs: "calc(100vw - 48px)", sm: width },
            height: 500,
            borderRadius: "20px",
            backgroundColor: "#0f172a",
            border: "1px solid rgba(255, 255, 255, 0.08)",
            boxShadow: "0 20px 40px rgba(0, 0, 0, 0.5)",
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
            zIndex: 999,
            transition: "width 0.3s cubic-bezier(0.16, 1, 0.3, 1)",
          }}
        >
          {/* Resize handle */}
          <Box
            onMouseDown={startResize}
            sx={{
              position: "absolute",
              left: isLeftAnchored ? "auto" : 0,
              right: isLeftAnchored ? 0 : "auto",
              top: 0,
              bottom: 0,
              width: "6px",
              cursor: "ew-resize",
              zIndex: 10,
              backgroundColor: isResizing ? "rgba(99, 102, 241, 0.3)" : "transparent",
              "&:hover": {
                backgroundColor: "rgba(99, 102, 241, 0.15)",
              },
            }}
          />

          {/* Header */}
          <Box
            sx={{
              p: 2,
              borderBottom: "1px solid rgba(255, 255, 255, 0.06)",
              background: "linear-gradient(to right, #1e293b, #0f172a)",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
              <AutoAwesome
                sx={{
                  fontSize: 18,
                  color: "#818cf8",
                  animation: loading ? "shimmerColor 3s infinite linear" : "none",
                  "@keyframes shimmerColor": {
                    "0%": { color: "#818cf8", filter: "drop-shadow(0 0 2px rgba(129,140,248,0.4))" },
                    "25%": { color: "#06b6d4", filter: "drop-shadow(0 0 4px rgba(6,182,212,0.6))" },
                    "50%": { color: "#ec4899", filter: "drop-shadow(0 0 5px rgba(236,72,153,0.6))" },
                    "75%": { color: "#a855f7", filter: "drop-shadow(0 0 4px rgba(168,85,247,0.6))" },
                    "100%": { color: "#818cf8", filter: "drop-shadow(0 0 2px rgba(129,140,248,0.4))" }
                  }
                }}
              />
              <Box sx={{ display: "flex", flexDirection: "column", gap: 0.35 }}>
                <Typography sx={{ fontSize: "0.875rem", fontWeight: 700, color: "#f8fafc", lineHeight: 1.1 }}>
                  Finter AI
                </Typography>
                <Typography sx={{ fontSize: "0.6875rem", color: "#22c55e", fontWeight: 500, display: "flex", alignItems: "center", gap: 0.5, lineHeight: 1.1 }}>
                  <span style={{ width: 6, height: 6, borderRadius: "50%", backgroundColor: "#22c55e" }}></span> Online
                </Typography>
              </Box>
            </Box>

            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              {messages.length > 1 && (
                <Tooltip title="Bersihkan Percakapan" arrow>
                  <IconButton
                    onClick={handleClearClick}
                    size="small"
                    sx={{
                      color: "#64748b",
                      transition: "background-color 0.2s, color 0.2s",
                      "&:hover": { color: "#ef4444", backgroundColor: "rgba(239, 68, 68, 0.08)" },
                    }}
                  >
                    <DeleteOutline sx={{ fontSize: 18 }} />
                  </IconButton>
                </Tooltip>
              )}
              <IconButton
                onClick={() => setIsOpen(false)}
                size="small"
                sx={{
                  color: "#64748b",
                  transition: "background-color 0.2s, color 0.2s",
                  "&:hover": { color: "#f8fafc", backgroundColor: "rgba(255, 255, 255, 0.08)" }
                }}
              >
                <Close sx={{ fontSize: 18 }} />
              </IconButton>
            </Box>
          </Box>

          {/* Messages List */}
          <Box
            ref={scrollRef}
            sx={{
              flex: 1,
              overflowY: "auto",
              p: 2.5,
              display: "flex",
              flexDirection: "column",
              gap: 2,
              backgroundColor: "#0b1329",
              backgroundImage: "radial-gradient(rgba(255,255,255,0.015) 1px, transparent 0)",
              backgroundSize: "24px 24px",
            }}
          >
            {isOpening ? (
              <>
                {[1, 2, 3].map((i) => (
                  <Box 
                    key={i} 
                    sx={{ 
                      display: "flex", 
                      justifyContent: i % 2 === 0 ? "flex-end" : "flex-start", 
                      gap: 1.25 
                    }}
                  >
                    <Skeleton 
                      variant="rounded" 
                      width={i === 2 ? "60%" : i === 1 ? "80%" : "70%"} 
                      height={i === 1 ? 70 : 50} 
                      animation="wave"
                      sx={{ 
                        bgcolor: "rgba(255, 255, 255, 0.04)", 
                        borderRadius: "12px" 
                      }} 
                    />
                  </Box>
                ))}
              </>
            ) : (
              <>
                {messages.map((m, idx) => {
                  const isBot = m.role === "model";
                  return (
                    <Box
                      key={idx}
                      sx={{
                        display: "flex",
                        justifyContent: isBot ? "flex-start" : "flex-end",
                        alignItems: "flex-start",
                        gap: 1.25,
                      }}
                    >
                      {isBot && <AutoAwesome sx={{ fontSize: 15, color: "#818cf8", mt: 0.75, mr: 0.25 }} />}
                      <Box
                        sx={{
                          maxWidth: "80%",
                          p: 1.75,
                          borderRadius: isBot ? "0px 16px 16px 16px" : "16px 0px 16px 16px",
                          backgroundColor: isBot ? "#1e293b" : "rgba(99, 102, 241, 0.2)",
                          border: isBot ? "1px solid rgba(255, 255, 255, 0.04)" : "1px solid rgba(99, 102, 241, 0.15)",
                        }}
                      >
                        {renderMarkdown(m.text)}
                      </Box>
                    </Box>
                  );
                })}

                {streamingText && (
                  <Box
                    sx={{
                      display: "flex",
                      justifyContent: "flex-start",
                      alignItems: "flex-start",
                      gap: 1.25,
                    }}
                  >
                    <AutoAwesome sx={{ fontSize: 15, color: "#818cf8", mt: 0.75, mr: 0.25 }} />
                    <Box
                      sx={{
                        maxWidth: "80%",
                        p: 1.75,
                        borderRadius: "0px 16px 16px 16px",
                        backgroundColor: "#1e293b",
                        border: "1px solid rgba(255, 255, 255, 0.04)",
                      }}
                    >
                      {renderMarkdown(streamingText)}
                    </Box>
                  </Box>
                )}

                {loading && (
                  <Box sx={{ display: "flex", alignItems: "center", gap: 1.25 }}>
                    <AutoAwesome
                      sx={{
                        fontSize: 15,
                        color: "#818cf8",
                        mr: 0.25,
                        animation: "shimmerColor 3s infinite linear",
                        "@keyframes shimmerColor": {
                          "0%": { color: "#818cf8", filter: "drop-shadow(0 0 2px rgba(129,140,248,0.4))" },
                          "25%": { color: "#06b6d4", filter: "drop-shadow(0 0 4px rgba(6,182,212,0.6))" },
                          "50%": { color: "#ec4899", filter: "drop-shadow(0 0 5px rgba(236,72,153,0.6))" },
                          "75%": { color: "#a855f7", filter: "drop-shadow(0 0 4px rgba(168,85,247,0.6))" },
                          "100%": { color: "#818cf8", filter: "drop-shadow(0 0 2px rgba(129,140,248,0.4))" }
                        }
                      }}
                    />
                    <Paper
                      sx={{
                        py: 1.25,
                        px: 1.75,
                        borderRadius: "0px 16px 16px 16px",
                        backgroundColor: "#1e293b",
                        border: "1px solid rgba(255, 255, 255, 0.04)",
                        display: "flex",
                        alignItems: "center",
                      }}
                    >
                      <Box sx={{ display: "flex", gap: 0.6, alignItems: "center" }}>
                        <Box
                          sx={{
                            width: 6,
                            height: 6,
                            borderRadius: "50%",
                            backgroundColor: "#818cf8",
                            animation: "pulseScale 1.2s infinite ease-in-out both",
                            animationDelay: "0s",
                            "@keyframes pulseScale": {
                              "0%, 80%, 100%": { transform: "scale(0.6)", opacity: 0.4 },
                              "40%": { transform: "scale(1.2)", opacity: 1 },
                            }
                          }}
                        />
                        <Box
                          sx={{
                            width: 6,
                            height: 6,
                            borderRadius: "50%",
                            backgroundColor: "#818cf8",
                            animation: "pulseScale 1.2s infinite ease-in-out both",
                            animationDelay: "0.2s",
                          }}
                        />
                        <Box
                          sx={{
                            width: 6,
                            height: 6,
                            borderRadius: "50%",
                            backgroundColor: "#818cf8",
                            animation: "pulseScale 1.2s infinite ease-in-out both",
                            animationDelay: "0.4s",
                          }}
                        />
                      </Box>
                    </Paper>
                  </Box>
                )}
              </>
            )}
          </Box>

          {/* Input Box */}
          <Box
            sx={{
              p: 2,
              backgroundColor: "#0f172a",
              borderTop: "1px solid rgba(255, 255, 255, 0.06)",
            }}
          >
            <ChatInput disabled={loading} onSend={handleSend} />
          </Box>
        </Paper>
      )}

      {/* Clear Confirmation Dialog */}
      <Dialog
        open={confirmOpen}
        onClose={() => setConfirmOpen(false)}
        PaperProps={{
          sx: {
            backgroundColor: "#1e293b",
            border: "1px solid rgba(255,255,255,0.08)",
            borderRadius: "16px",
            color: "#f8fafc",
          },
        }}
      >
        <DialogTitle sx={{ fontWeight: 700, fontSize: "1.05rem" }}>
          Bersihkan Obrolan?
        </DialogTitle>
        <DialogContent>
          <DialogContentText sx={{ color: "#94a3b8", fontSize: "0.8125rem" }}>
            Seluruh riwayat percakapan Anda dengan Finter AI akan dihapus secara permanen dari basis data. Tindakan ini tidak dapat dibatalkan.
          </DialogContentText>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2.5 }}>
          <Button
            onClick={() => setConfirmOpen(false)}
            sx={{ color: "#94a3b8", fontSize: "0.75rem", fontWeight: 600, textTransform: "none" }}
          >
            Batal
          </Button>
          <Button
            onClick={handleConfirmClear}
            variant="contained"
            color="error"
            sx={{
              borderRadius: "8px",
              fontSize: "0.75rem",
              fontWeight: 600,
              backgroundColor: "#ef4444",
              "&:hover": { backgroundColor: "#dc2626" },
              textTransform: "none",
            }}
          >
            Hapus
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
}

function ChatInput({ onSend, disabled }: { onSend: (text: string) => void; disabled: boolean }) {
  const [localInput, setLocalInput] = useState("");

  const handleTriggerSend = () => {
    const val = localInput.trim();
    if (!val || disabled) return;
    onSend(val);
    setLocalInput("");
  };

  return (
    <TextField
      fullWidth
      multiline
      maxRows={5}
      size="small"
      variant="outlined"
      placeholder="Tanyakan analisis, catat transaksi..."
      value={localInput}
      onChange={(e) => setLocalInput(e.target.value)}
      onKeyDown={(e) => {
        if (e.key === "Enter" && !e.shiftKey) {
          e.preventDefault();
          handleTriggerSend();
        }
      }}
      disabled={disabled}
      sx={{
        "& .MuiOutlinedInput-root": {
          borderRadius: "12px",
          backgroundColor: "#070c19",
          fontSize: "0.8125rem",
          color: "#f8fafc",
          "& fieldset": { borderColor: "rgba(255,255,255,0.06)" },
          "& hover fieldset": { borderColor: "rgba(99,102,241,0.3)" },
          "&.Mui-focused fieldset": { borderColor: "#6366f1" },
        },
        "& .MuiInputAdornment-root .MuiSvgIcon-root": {
          color: (disabled || !localInput.trim())
            ? "rgba(255,255,255,0.2) !important"
            : "#ffffff !important"
        }
      }}
      slotProps={{
        input: {
          endAdornment: (
            <InputAdornment position="end" sx={{ alignSelf: "flex-end", my: 0.8 }}>
              <IconButton
                onClick={handleTriggerSend}
                disabled={disabled || !localInput.trim()}
                sx={{
                  backgroundColor: "#6366f1",
                  color: "#ffffff !important",
                  width: 30,
                  height: 30,
                  borderRadius: "50%",
                  "&:hover": { backgroundColor: "#4f46e5" },
                  "&.Mui-disabled": {
                    backgroundColor: "rgba(255, 255, 255, 0.08) !important",
                    color: "rgba(255, 255, 255, 0.2) !important"
                  },
                  transition: "all 0.2s ease",
                }}
              >
                <Send
                  sx={{
                    fontSize: 14,
                    ml: 0.25,
                    color: (disabled || !localInput.trim()) ? "rgba(255,255,255,0.2) !important" : "#ffffff !important"
                  }}
                />
              </IconButton>
            </InputAdornment>
          ),
        }
      }}
    />
  );
}
