"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import {
  Dashboard,
  TrendingUp,
  TrendingDown,
  Assessment,
  Settings,
  ExpandLess,
  ExpandMore,
  AccountBalance,
  ChevronLeft,
  ChevronRight,
  SwapHoriz,
  Savings,
  ShowChart,
  AccountBalanceWallet,
  ReceiptRounded,
  BarChart,
  Inventory2,
  Menu,
  CreditCard,
} from "@mui/icons-material";
import {
  Box,
  Collapse,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Popover,
  Tooltip,
  Typography,
} from "@mui/material";

// ─── Types ────────────────────────────────────────────────────────────────────
type NavLeaf = { label: string; icon: React.ReactNode; href: string };

type NavSubGroup = {
  label: string;
  icon: React.ReactNode;
  subChildren: NavLeaf[];
};

type NavGroup = {
  label: string;
  icon: React.ReactNode;
  children: (NavLeaf | NavSubGroup)[];
};

type NavSingle = { label: string; icon: React.ReactNode; href: string };
type NavItem   = NavSingle | NavGroup;

const isNavGroup = (item: NavItem): item is NavGroup =>
  "children" in item;

const isSubGroup = (item: NavLeaf | NavSubGroup): item is NavSubGroup =>
  "subChildren" in item;

// ─── Nav Tree ─────────────────────────────────────────────────────────────────
const navItems: NavItem[] = [
  {
    label: "Dashboard",
    icon: <Dashboard fontSize="small" />,
    href: "/dashboard",
  },
  {
    label: "Transactions",
    icon: <ReceiptRounded fontSize="small" />,
    children: [
      { label: "Income",   icon: <TrendingUp fontSize="small" />,   href: "/income"   },
      { label: "Outcome",  icon: <TrendingDown fontSize="small" />, href: "/outcome"  },
      { label: "Transfer", icon: <SwapHoriz fontSize="small" />,    href: "/transfer" },
    ],
  },
  {
    label: "Accounts",
    icon: <AccountBalanceWallet fontSize="small" />,
    children: [
      { label: "Cashflow", icon: <AccountBalance fontSize="small" />, href: "/accounts/cashflow" },
      { label: "Saving",   icon: <Savings fontSize="small" />,        href: "/accounts/saving"   },
      {
        label: "Investment",
        icon: <ShowChart fontSize="small" />,
        subChildren: [
          { label: "Overview", icon: <BarChart fontSize="small" />,   href: "/accounts/investment/overview" },
          { label: "Holding",  icon: <Inventory2 fontSize="small" />, href: "/accounts/investment/holding"  },
          { label: "Trading",  icon: <SwapHoriz fontSize="small" />,  href: "/accounts/investment/trading"  },
        ],
      },
      { label: "Liability", icon: <CreditCard fontSize="small" />,    href: "/accounts/liability" },
    ],
  },
  {
    label: "Reports",
    icon: <Assessment fontSize="small" />,
    children: [
      { label: "Cashflow",   icon: <AccountBalance fontSize="small" />, href: "/report/cashflow"   },
      { label: "Saving",     icon: <Savings fontSize="small" />,        href: "/report/saving"     },
      { label: "Investment", icon: <ShowChart fontSize="small" />,      href: "/report/investment" },
      { label: "Liability",  icon: <CreditCard fontSize="small" />,     href: "/report/liability"  },
    ],
  },
  {
    label: "Settings",
    icon: <Settings fontSize="small" />,
    href: "/settings",
  },
];

// ─── Shared style constants ────────────────────────────────────────────────────
// All nav items use EXACTLY the same size/typography — only indentation differs
const NAV_ITEM_SX = (active: boolean) => ({
  borderRadius: "8px",
  mb: 0.5,
  px: 1.5,
  py: 0.875,       // consistent vertical padding
  minHeight: 38,   // consistent height for every level
  color: active ? "#818cf8" : "#94a3b8",
  backgroundColor: active ? "rgba(99,102,241,0.12)" : "transparent",
  "&:hover": { backgroundColor: "rgba(99,102,241,0.08)", color: "#c7d2fe" },
});

const NAV_TEXT_PROPS = (active: boolean) => ({
  fontSize: "0.8125rem",   // same font size everywhere
  fontWeight: active ? 600 : 400,
});

const NAV_ICON_SX = (active: boolean, minWidth = 32) => ({
  color: active ? "#818cf8" : "#94a3b8",
  minWidth,
});

// ─── Open state keys ──────────────────────────────────────────────────────────
type OpenKey = "Transactions" | "Accounts" | "Investment" | "Reports";

// ─── Component ────────────────────────────────────────────────────────────────
export default function Sidebar() {
  const pathname   = usePathname();
  const startsWith = (p: string) => pathname.startsWith(p);
  const isActive   = (href: string) => pathname === href;

  const [open, setOpen] = useState<Record<OpenKey, boolean>>({
    Transactions: startsWith("/income") || startsWith("/outcome") || startsWith("/transfer"),
    Accounts:     startsWith("/accounts"),
    Investment:   startsWith("/accounts/investment"),
    Reports:      startsWith("/report"),
  });

  const [collapsed, setCollapsed] = useState(false);
  const [logoHovered, setLogoHovered] = useState(false);
  const [mode, setMode] = useState<"full" | "tight" | "close">("full");
  const [mobileOpen, setMobileOpen] = useState(false);
  const isCollapsed = mode === "close" ? false : collapsed;

  useEffect(() => {
    const handleResize = () => {
      const w = window.innerWidth;
      if (w > 1200) {
        setMode("full");
        setCollapsed(false);
        setMobileOpen(false);
      } else if (w >= 768) {
        setMode("tight");
        setCollapsed(true);
        setMobileOpen(false);
      } else {
        setMode("close");
        setCollapsed(true);
      }
    };
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    const handleTourStart = () => {
      setOpen({
        Transactions: true,
        Accounts: true,
        Investment: true,
        Reports: true,
      });
      setCollapsed(false);
    };

    window.addEventListener("finter-tour-start", handleTourStart);
    return () => window.removeEventListener("finter-tour-start", handleTourStart);
  }, []);

  // Collapsed flyout popover
  const [popoverAnchor, setPopoverAnchor] = useState<HTMLElement | null>(null);
  const [popoverLabel,  setPopoverLabel]  = useState("");
  const [popoverChildren, setPopoverChildren] = useState<(NavLeaf | NavSubGroup)[]>([]);
  const [subPopoverAnchor, setSubPopoverAnchor] = useState<HTMLElement | null>(null);
  const [subPopoverLeaves, setSubPopoverLeaves] = useState<NavLeaf[]>([]);

  const toggle = (key: OpenKey) =>
    setOpen((prev) => ({ ...prev, [key]: !prev[key] }));

  const flattenLeaves = (group: NavGroup): NavLeaf[] => {
    const out: NavLeaf[] = [];
    for (const child of group.children) {
      if (isSubGroup(child)) out.push(...child.subChildren);
      else out.push(child);
    }
    return out;
  };

  const groupIsActive = (group: NavGroup): boolean => {
    for (const child of group.children) {
      if (isSubGroup(child)) {
        if (child.subChildren.some((l) => startsWith(l.href))) return true;
      } else {
        if (startsWith(child.href)) return true;
      }
    }
    return false;
  };

  // ── Render: leaf item (level 2) ─────────────────────────────────────────────
  const renderLeaf = (leaf: NavLeaf) => {
    const active = isActive(leaf.href);
    const labelKey = leaf.label.toLowerCase().replace(/\s+/g, "-");
    const isReport = leaf.href.startsWith("/report/");
    const tourId = isReport ? `tour-sidebar-report-${labelKey}` : `tour-sidebar-${labelKey}`;
    return (
      <Link key={leaf.href} href={leaf.href as any} style={{ textDecoration: "none" }} onClick={() => { if (mode === "close") setMobileOpen(false); }}>
        <ListItemButton id={tourId} sx={NAV_ITEM_SX(active)}>
          <ListItemIcon sx={NAV_ICON_SX(active)}>
            {leaf.icon}
          </ListItemIcon>
          <ListItemText
            primary={leaf.label}
            primaryTypographyProps={NAV_TEXT_PROPS(active)}
          />
        </ListItemButton>
      </Link>
    );
  };

  // ── Render: Investment sub-group (level 2 toggle + level 3 leaves) ──────────
  const renderSubGroup = (sub: NavSubGroup) => {
    const subActive = sub.subChildren.some((l) => startsWith(l.href));
    const isOpen    = open.Investment;
    const labelKey = sub.label.toLowerCase().replace(/\s+/g, "-");

    return (
      <div key={sub.label}>
        {/* Investment toggle row — same size as siblings */}
        <ListItemButton
          id={`tour-sidebar-${labelKey}`}
          onClick={() => toggle("Investment")}
          sx={NAV_ITEM_SX(subActive)}
        >
          <ListItemIcon sx={NAV_ICON_SX(subActive)}>
            {sub.icon}
          </ListItemIcon>
          <ListItemText
            primary={sub.label}
            primaryTypographyProps={NAV_TEXT_PROPS(subActive)}
          />
          {isOpen
            ? <ExpandLess sx={{ fontSize: 16, color: "#475569" }} />
            : <ExpandMore sx={{ fontSize: 16, color: "#475569" }} />}
        </ListItemButton>

        {/* Level-3 leaves — slightly indented but same button size, no connector line */}
        <Collapse in={isOpen} timeout="auto" unmountOnExit>
          <List disablePadding dense sx={{ pl: 2 }}>
            {sub.subChildren.map((leaf) => {
              const active = isActive(leaf.href);
              const labelKey = leaf.label.toLowerCase().replace(/\s+/g, "-");
              return (
                <Link key={leaf.href} href={leaf.href as any} style={{ textDecoration: "none" }} onClick={() => { if (mode === "close") setMobileOpen(false); }}>
                  <ListItemButton id={`tour-sidebar-${labelKey}`} sx={NAV_ITEM_SX(active)}>
                    <ListItemIcon sx={NAV_ICON_SX(active)}>
                      {leaf.icon}
                    </ListItemIcon>
                    <ListItemText
                      primary={leaf.label}
                      primaryTypographyProps={NAV_TEXT_PROPS(active)}
                    />
                  </ListItemButton>
                </Link>
              );
            })}
          </List>
        </Collapse>
      </div>
    );
  };

  // ── Render: top-level group (Transactions, Accounts, Reports) ───────────────
  const renderGroup = (item: NavGroup) => {
    const active = groupIsActive(item);
    const isOpen = open[item.label as OpenKey] ?? false;
    const labelKey = item.label.toLowerCase().replace(/\s+/g, "-");

    return (
      <div key={item.label}>
        <Tooltip title={isCollapsed ? item.label : ""} placement="right" arrow>
          <ListItemButton
            id={`tour-sidebar-${labelKey}`}
            onClick={(e) => {
              if (isCollapsed) {
                setPopoverAnchor(e.currentTarget);
                setPopoverLabel(item.label);
                setPopoverChildren(item.children);
                setSubPopoverAnchor(null);
              } else {
                toggle(item.label as OpenKey);
              }
            }}
            sx={{
              ...NAV_ITEM_SX(active),
              justifyContent: isCollapsed ? "center" : "flex-start",
            }}
          >
            <ListItemIcon sx={{ ...NAV_ICON_SX(active), minWidth: isCollapsed ? 0 : 32 }}>
              {item.icon}
            </ListItemIcon>
            {!isCollapsed && (
              <>
                <ListItemText
                  primary={item.label}
                  primaryTypographyProps={NAV_TEXT_PROPS(active)}
                />
                {isOpen ? <ExpandLess sx={{ fontSize: 16 }} /> : <ExpandMore sx={{ fontSize: 16 }} />}
              </>
            )}
          </ListItemButton>
        </Tooltip>

        {!isCollapsed && (
          <Collapse in={isOpen} timeout="auto" unmountOnExit>
            <List disablePadding dense sx={{ pl: 2 }}>
              {item.children.map((child) =>
                isSubGroup(child) ? renderSubGroup(child) : renderLeaf(child)
              )}
            </List>
          </Collapse>
        )}
      </div>
    );
  };

  // ── Render: single item (Dashboard, Settings) ───────────────────────────────
  const renderSingle = (item: NavSingle) => {
    const active = isActive(item.href);
    const labelKey = item.label.toLowerCase().replace(/\s+/g, "-");
    return (
      <Link key={item.href} href={item.href as any} style={{ textDecoration: "none" }} onClick={() => { if (mode === "close") setMobileOpen(false); }}>
        <Tooltip title={isCollapsed ? item.label : ""} placement="right" arrow>
          <ListItemButton
            id={`tour-sidebar-${labelKey}`}
            sx={{
              ...NAV_ITEM_SX(active),
              justifyContent: isCollapsed ? "center" : "flex-start",
            }}
          >
            <ListItemIcon sx={{ ...NAV_ICON_SX(active), minWidth: isCollapsed ? 0 : 32 }}>
              {item.icon}
            </ListItemIcon>
            {!isCollapsed && (
              <ListItemText
                primary={item.label}
                primaryTypographyProps={NAV_TEXT_PROPS(active)}
              />
            )}
          </ListItemButton>
        </Tooltip>
      </Link>
    );
  };

  // ── Main render ─────────────────────────────────────────────────────────────
  return (
    <>
      {/* Mobile Top Bar */}
      {mode === "close" && (
        <div className="fixed top-0 left-0 right-0 h-14 bg-[#0f172a]/95 border-b border-slate-800/80 backdrop-blur-md z-30 flex items-center px-4 shadow-md">
          <button
            onClick={() => setMobileOpen((o) => !o)}
            className="w-9 h-9 rounded-lg bg-slate-800/80 border border-slate-700 flex items-center justify-center text-slate-400 hover:text-white hover:bg-indigo-500 hover:border-indigo-500 transition-all shadow-sm"
          >
            <Menu sx={{ fontSize: 18 }} />
          </button>
          <Link href="/">
            <img src="/images/logo_light.png" alt="Finter" className="h-6 object-contain ml-3 cursor-pointer" />
          </Link>
        </div>
      )}

      {/* Backdrop for Mobile Screen */}
      {mode === "close" && mobileOpen && (
        <div
          onClick={() => setMobileOpen(false)}
          className="fixed inset-0 bg-black/60 z-40 backdrop-blur-xs transition-all duration-300"
        />
      )}

      <aside
        id="tour-sidebar"
        className={`flex flex-col h-screen bg-[#0f172a] border-r border-slate-800 transition-all duration-300 ${
          mode === "close"
            ? `fixed left-0 top-0 z-50 shadow-2xl ${mobileOpen ? "w-60" : "w-0 overflow-hidden border-r-0"}`
            : `relative ${collapsed ? "w-16" : "w-60"}`
        }`}
      >
        {/* Logo & Toggle Header */}
        <div className="border-b border-slate-800 h-16 flex items-center justify-center relative w-full">
          {isCollapsed ? (
            <Tooltip title="Buka Sidebar" placement="right" arrow>
              <button
                onClick={() => {
                  setCollapsed(false);
                  setLogoHovered(false);
                }}
                onMouseEnter={() => setLogoHovered(true)}
                onMouseLeave={() => setLogoHovered(false)}
                className="w-10 h-10 rounded-lg flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-800/80 transition-all cursor-pointer"
              >
                {logoHovered ? (
                  <ChevronRight sx={{ fontSize: 22, color: "#818cf8" }} />
                ) : (
                  <img src="/icon.png" alt="Finter" className="w-8 h-8 object-contain" />
                )}
              </button>
            </Tooltip>
          ) : (
            <div className="flex items-center justify-between w-full px-4">
              <Link href="/">
                <img src="/images/logo_light.png" alt="Finter" className="h-7 object-contain cursor-pointer" />
              </Link>
              <Tooltip title="Tutup Sidebar" placement="bottom" arrow>
                <button
                  onClick={() => {
                    if (mode === "close") {
                      setMobileOpen(false);
                    } else {
                      setCollapsed(true);
                    }
                  }}
                  className="w-10 h-10 rounded-lg flex items-center justify-center text-slate-500 hover:text-slate-200 hover:bg-slate-800/80 transition-all cursor-pointer"
                >
                  <ChevronLeft sx={{ fontSize: 22 }} />
                </button>
              </Tooltip>
            </div>
          )}
        </div>

        {/* Nav */}
        <nav className="flex-1 overflow-y-auto py-4 px-2">
          <List disablePadding dense>
            {navItems.map((item) =>
              isNavGroup(item) ? renderGroup(item) : renderSingle(item as NavSingle)
            )}
          </List>
        </nav>
      </aside>

      {/* Flyout Popover — collapsed sidebar */}
      <Popover
        open={Boolean(popoverAnchor)}
        anchorEl={popoverAnchor}
        onClose={() => { setPopoverAnchor(null); setSubPopoverAnchor(null); }}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
        transformOrigin={{ vertical: "top", horizontal: "left" }}
        slotProps={{
          paper: {
            sx: {
              ml: 1,
              backgroundColor: "#1e293b",
              border: "1px solid #334155",
              borderRadius: "10px",
              boxShadow: "0 8px 32px rgba(0,0,0,0.4)",
              minWidth: 170,
              overflow: "hidden",
            },
          },
        }}
      >
        <div className="px-3 py-2 border-b border-slate-700">
          <Typography sx={{ fontSize: "0.7rem", color: "#64748b", textTransform: "uppercase", letterSpacing: "0.08em", fontWeight: 600 }}>
            {popoverLabel}
          </Typography>
        </div>
        <List dense sx={{ mt: "10px !important", pt: "0px !important", pb: "6px !important", px: "6px !important" }}>
          {popoverChildren.map((child) => {
            if (isSubGroup(child)) {
              const active = child.subChildren.some((l) => startsWith(l.href));
              return (
                <ListItemButton
                  key={child.label}
                  onClick={(e) => {
                    setSubPopoverAnchor(e.currentTarget);
                    setSubPopoverLeaves(child.subChildren);
                  }}
                  sx={{
                    borderRadius: "8px", mb: 0.25, px: 1.25, py: 0.875, minHeight: 38,
                    color: active ? "#818cf8" : "#94a3b8",
                    backgroundColor: active ? "rgba(99,102,241,0.15)" : "transparent",
                    "&:hover": { backgroundColor: "rgba(99,102,241,0.1)", color: "#c7d2fe" },
                  }}
                >
                  <ListItemIcon sx={{ color: active ? "#818cf8" : "#64748b", minWidth: 28 }}>
                    {child.icon}
                  </ListItemIcon>
                  <ListItemText
                    primary={child.label}
                    primaryTypographyProps={{ fontSize: "0.8125rem", fontWeight: active ? 600 : 400 }}
                  />
                  <ChevronRight sx={{ fontSize: 14, color: "#64748b", ml: "auto" }} />
                </ListItemButton>
              );
            }

            const active = isActive(child.href);
            return (
              <Link key={child.href} href={child.href as any} style={{ textDecoration: "none" }} onClick={() => { setPopoverAnchor(null); setSubPopoverAnchor(null); }}>
                <ListItemButton
                  sx={{
                    borderRadius: "8px", mb: 0.25, px: 1.25, py: 0.875, minHeight: 38,
                    color: active ? "#818cf8" : "#94a3b8",
                    backgroundColor: active ? "rgba(99,102,241,0.15)" : "transparent",
                    "&:hover": { backgroundColor: "rgba(99,102,241,0.1)", color: "#c7d2fe" },
                  }}
                >
                  <ListItemIcon sx={{ color: active ? "#818cf8" : "#64748b", minWidth: 28 }}>
                    {child.icon}
                  </ListItemIcon>
                  <ListItemText
                    primary={child.label}
                    primaryTypographyProps={{ fontSize: "0.8125rem", fontWeight: active ? 600 : 400 }}
                  />
                </ListItemButton>
              </Link>
            );
          })}
        </List>
      </Popover>

      {/* Secondary Cascading Popover for Sub-Groups */}
      <Popover
        open={Boolean(subPopoverAnchor)}
        anchorEl={subPopoverAnchor}
        onClose={() => setSubPopoverAnchor(null)}
        anchorOrigin={{ vertical: "top", horizontal: "right" }}
        transformOrigin={{ vertical: "top", horizontal: "left" }}
        slotProps={{
          paper: {
            sx: {
              ml: 1,
              backgroundColor: "#1e293b",
              border: "1px solid #334155",
              borderRadius: "10px",
              boxShadow: "0 8px 32px rgba(0,0,0,0.4)",
              minWidth: 150,
              overflow: "hidden",
            },
          },
        }}
      >
        <List disablePadding dense sx={{ py: 0.75, px: 0.75 }}>
          {subPopoverLeaves.map((leaf) => {
            const active = isActive(leaf.href);
            return (
              <Link key={leaf.href} href={leaf.href as any} style={{ textDecoration: "none" }} onClick={() => { setPopoverAnchor(null); setSubPopoverAnchor(null); }}>
                <ListItemButton
                  sx={{
                    borderRadius: "8px", mb: 0.25, px: 1.25, py: 0.875, minHeight: 38,
                    color: active ? "#818cf8" : "#94a3b8",
                    backgroundColor: active ? "rgba(99,102,241,0.15)" : "transparent",
                    "&:hover": { backgroundColor: "rgba(99,102,241,0.1)", color: "#c7d2fe" },
                  }}
                >
                  <ListItemIcon sx={{ color: active ? "#818cf8" : "#64748b", minWidth: 28 }}>
                    {leaf.icon}
                  </ListItemIcon>
                  <ListItemText
                    primary={leaf.label}
                    primaryTypographyProps={{ fontSize: "0.8125rem", fontWeight: active ? 600 : 400 }}
                  />
                </ListItemButton>
              </Link>
            );
          })}
        </List>
      </Popover>
    </>
  );
}