"use client";

import { useEffect, useState } from "react";

export default function PageLoader() {
  const [show, setShow] = useState<boolean>(true);

  useEffect(() => {
    // Check if the document has the 'no-loader' class, which means
    // it's not a first access and not a page reload.
    const hasNoLoader = document.documentElement.classList.contains("no-loader");
    
    if (hasNoLoader) {
      setShow(false);
      return;
    }

    // Set visited flag in sessionStorage for subsequent normal navigations
    sessionStorage.setItem("finter_visited", "true");

    // Fade out and unmount from DOM after loader animations finish (4.4s total)
    const timer = setTimeout(() => {
      setShow(false);
    }, 4400);

    return () => clearTimeout(timer);
  }, []);

  if (!show) return null;

  return (
    <div className="loader">
      <div className="logo">
        <div className="base"></div>
        <div className="sweep"></div>
        <div className="final"></div>
      </div>
    </div>
  );
}
