import { showToast } from "@/components/ToastNotification";
import { getAccountsAction } from "@/features/account/actions";
import { createTradeAction, getTradesAction } from "@/features/investment/actions";
import { createIncomeAction, updateIncomeAction, getIncomeListAction } from "@/features/income/actions";
import { createOutcomeAction, updateOutcomeAction, getOutcomeListAction } from "@/features/outcome/actions";
import { createTransferAction, updateTransferAction, getTransferListAction } from "@/features/transfer/actions";
import { createLedgerAction, getLedgerListAction } from "@/features/ledger/actions";
import { createEnumAction } from "@/features/enum/actions";
import { refreshExchangeRatesAction } from "@/features/exchange/actions";

export async function executeAgenticActions(
  parsedActions: any[],
  router: any,
  formatAmount: (amount: number, accId: number) => string,
  parseCleanFloat: (val: string | undefined) => number
) {
  for (const action of parsedActions) {
    try {
      if (action.type === "navigate" && action.path) {
        router.push(action.path);
        showToast(`Membuka halaman ${action.path}...`, "info");
        await new Promise((resolve) => setTimeout(resolve, 1000));
      } else if (action.type === "trade") {
        let accId = parseInt(action.accountId || "1");
        if (!action.accountId) {
          const accRes = await getAccountsAction();
          if (accRes.success && Array.isArray(accRes.data) && accRes.data.length > 0) {
            const investAcc = accRes.data.find((a: any) => a.bucket === "INVESTMENT");
            if (investAcc) {
              accId = investAcc.id;
            }
          }
        }
        const payload = {
          accountId: accId,
          symbol: sanitizeInput(action.symbol, "GENERIC"),
          nama: sanitizeInput(action.symbol, "GENERIC"),
          quantity: parseCleanFloat(action.quantity),
          total: parseCleanFloat(action.total),
          note: sanitizeInput(action.note, "Transaksi otomatis via Finter AI"),
        };

        const tradeRes = await createTradeAction(payload);
        if (tradeRes.success) {
          showToast(`Trading ${payload.symbol} dicatat sukses!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(tradeRes.error || "Gagal mencatatkan trading.", "error");
        }
      } else if (action.type === "create-income") {
        const payload = {
          date: action.date || new Date().toISOString().split("T")[0],
          amount: parseCleanFloat(action.amount),
          accountId: parseInt(action.accountId || "1"),
          typeId: parseInt(action.typeId || "1"),
          sourceId: parseInt(action.sourceId || "1"),
          note: sanitizeInput(action.note, "Pemasukan dicatat otomatis via Finter AI"),
        };

        const res = await createIncomeAction(payload);
        if (res.success) {
          showToast(`Pemasukan ${formatAmount(payload.amount, payload.accountId)} dicatat sukses!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal mencatatkan pemasukan.", "error");
        }
      } else if (action.type === "edit-income") {
        const payload = {
          id: parseInt(action.id),
          date: action.date || new Date().toISOString().split("T")[0],
          amount: parseCleanFloat(action.amount),
          accountId: parseInt(action.accountId || "1"),
          typeId: parseInt(action.typeId || "1"),
          sourceId: parseInt(action.sourceId || "1"),
          note: sanitizeInput(action.note, "Pemasukan diperbarui via Finter AI"),
        };

        const res = await updateIncomeAction(payload);
        if (res.success) {
          showToast(`Pemasukan #${payload.id} sukses diperbarui!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal memperbarui pemasukan.", "error");
        }
      } else if (action.type === "create-outcome") {
        const payload = {
          date: action.date || new Date().toISOString().split("T")[0],
          amount: parseCleanFloat(action.amount),
          accountId: parseInt(action.accountId || "1"),
          categoryId: parseInt(action.categoryId || "1"),
          subcategoryId: parseInt(action.subcategoryId || "1"),
          note: sanitizeInput(action.note, "Pengeluaran dicatat otomatis via Finter AI"),
        };

        const res = await createOutcomeAction(payload);
        if (res.success) {
          showToast(`Pengeluaran ${formatAmount(payload.amount, payload.accountId)} dicatat sukses!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal mencatatkan pengeluaran.", "error");
        }
      } else if (action.type === "edit-outcome") {
        const payload = {
          id: parseInt(action.id),
          date: action.date || new Date().toISOString().split("T")[0],
          amount: parseCleanFloat(action.amount),
          accountId: parseInt(action.accountId || "1"),
          categoryId: parseInt(action.categoryId || "1"),
          subcategoryId: parseInt(action.subcategoryId || "1"),
          note: sanitizeInput(action.note, "Pengeluaran diperbarui via Finter AI"),
        };

        const res = await updateOutcomeAction(payload);
        if (res.success) {
          showToast(`Pengeluaran #${payload.id} sukses diperbarui!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal memperbarui pengeluaran.", "error");
        }
      } else if (action.type === "create-transfer") {
        const payload = {
          date: action.date || new Date().toISOString().split("T")[0],
          amount: parseCleanFloat(action.amount),
          fromAccountId: parseInt(action.fromAccountId || "1"),
          toAccountId: parseInt(action.toAccountId || "2"),
          feeFixed: parseCleanFloat(action.feeFixed),
          feePercent: parseCleanFloat(action.feePercent),
          note: sanitizeInput(action.note, "Transfer otomatis via Finter AI"),
        };

        const res = await createTransferAction(payload);
        if (res.success) {
          showToast(`Transfer ${formatAmount(payload.amount, payload.fromAccountId)} dicatat sukses!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal mencatatkan transfer.", "error");
        }
      } else if (action.type === "edit-transfer") {
        const payload = {
          id: parseInt(action.id),
          date: action.date || new Date().toISOString().split("T")[0],
          amount: parseCleanFloat(action.amount),
          fromAccountId: parseInt(action.fromAccountId || "1"),
          toAccountId: parseInt(action.toAccountId || "2"),
          feeFixed: parseCleanFloat(action.feeFixed),
          feePercent: parseCleanFloat(action.feePercent),
          note: sanitizeInput(action.note, "Transfer diperbarui via Finter AI"),
        };

        const res = await updateTransferAction(payload);
        if (res.success) {
          showToast(`Transfer #${payload.id} sukses diperbarui!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal memperbarui transfer.", "error");
        }
      } else if (action.type === "download-report") {
        const cat = action.category || "cashflow";
        showToast(`Menyiapkan laporan PDF ${cat.toUpperCase()}...`, "info");

        const { exportToPDF } = await import("@/lib/report-pdf");

        if (cat === "cashflow") {
          const incRes = await getIncomeListAction({ pageSize: 500 });
          const outRes = await getOutcomeListAction({ pageSize: 500 });
          const incomes = incRes.success ? incRes.data?.items || [] : [];
          const outcomes = outRes.success ? outRes.data?.items || [] : [];

          const rows = [
            ...incomes.map((i: any) => [
              new Date(i.date).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" }),
              i.note || "Pemasukan",
              "Pemasukan",
              i.categoryName || "Lainnya",
              `+Rp ${Number(i.amount).toLocaleString("id-ID")}`
            ]),
            ...outcomes.map((o: any) => [
              new Date(o.date).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" }),
              o.note || "Pengeluaran",
              "Pengeluaran",
              o.categoryName || "Lainnya",
              `-Rp ${Number(o.amount).toLocaleString("id-ID")}`
            ])
          ].sort((a, b) => new Date(b[0]).getTime() - new Date(a[0]).getTime());

          const totalInc = incomes.reduce((sum: number, i: any) => sum + Number(i.amount), 0);
          const totalOut = outcomes.reduce((sum: number, o: any) => sum + Number(o.amount), 0);
          const netCashflow = totalInc - totalOut;

          exportToPDF(
            "Laporan Arus Kas (Cashflow)",
            ["Tanggal", "Keterangan", "Tipe", "Kategori", "Nominal"],
            rows,
            "Laporan_Cashflow_Finter.pdf",
            [
              { label: "Total Transaksi", value: `${rows.length} entri` },
              { label: "Total Pemasukan", value: `Rp ${totalInc.toLocaleString("id-ID")}` },
              { label: "Total Pengeluaran", value: `Rp ${totalOut.toLocaleString("id-ID")}` },
              { label: "Net Cashflow", value: `Rp ${netCashflow.toLocaleString("id-ID")}` }
            ]
          );
          showToast("Laporan Cashflow PDF berhasil diunduh!", "success");
        } else if (cat === "saving") {
          const ledgerRes = await getLedgerListAction({ pageSize: 500 });
          const items = ledgerRes.success && Array.isArray(ledgerRes.data) ? ledgerRes.data : [];

          const rows = items.map((l: any) => [
            new Date(l.date).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" }),
            l.note || "Mutasi Tabungan",
            l.direction === "CREDIT" ? "Penyetoran" : "Penarikan",
            `Rp ${Number(l.amount).toLocaleString("id-ID")}`
          ]);

          const totalDeposit = items.reduce((sum: number, l: any) => sum + (l.direction === "CREDIT" ? Number(l.amount) : 0), 0);
          const totalWithdraw = items.reduce((sum: number, l: any) => sum + (l.direction === "DEBIT" ? Number(l.amount) : 0), 0);
          const netSaving = totalDeposit - totalWithdraw;

          exportToPDF(
            "Laporan Mutasi Tabungan (Saving)",
            ["Tanggal", "Keterangan", "Jenis Mutasi", "Nominal"],
            rows,
            "Laporan_Tabungan_Finter.pdf",
            [
              { label: "Total Transaksi", value: `${rows.length} entri` },
              { label: "Total Penyetoran", value: `Rp ${totalDeposit.toLocaleString("id-ID")}` },
              { label: "Total Penarikan", value: `Rp ${totalWithdraw.toLocaleString("id-ID")}` },
              { label: "Saldo Bersih", value: `Rp ${netSaving.toLocaleString("id-ID")}` }
            ]
          );
          showToast("Laporan Tabungan PDF berhasil diunduh!", "success");
        } else if (cat === "investment") {
          const tradeRes = await getTradesAction();
          const items = tradeRes.success && Array.isArray(tradeRes.data) ? tradeRes.data : [];

          const rows = items.map((t: any) => [
            new Date(t.tanggal).toLocaleDateString("id-ID", { day: "2-digit", month: "short", year: "numeric" }),
            t.asset,
            t.type === "BUY" ? "Pembelian" : "Penjualan",
            `${Number(t.jumlahAwal).toLocaleString("id-ID")} unit`,
            `Rp ${Number(t.jumlahAkhir).toLocaleString("id-ID")}`
          ]);

          const totalBuy = items.reduce((sum: number, t: any) => sum + (t.type === "BUY" ? Number(t.jumlahAkhir) : 0), 0);
          const totalSell = items.reduce((sum: number, t: any) => sum + (t.type === "SELL" ? Number(t.jumlahAkhir) : 0), 0);

          exportToPDF(
            "Laporan Portofolio Investasi",
            ["Tanggal", "Simbol", "Tipe", "Jumlah", "Total Nilai"],
            rows,
            "Laporan_Investasi_Finter.pdf",
            [
              { label: "Total Transaksi", value: `${rows.length} entri` },
              { label: "Total Pembelian", value: `Rp ${totalBuy.toLocaleString("id-ID")}` },
              { label: "Total Penjualan", value: `Rp ${totalSell.toLocaleString("id-ID")}` }
            ]
          );
          showToast("Laporan Investasi PDF berhasil diunduh!", "success");
        }
      } else if (action.type === "create-saving") {
        let accId = parseInt(action.accountId || "2");
        if (!action.accountId) {
          const accRes = await getAccountsAction();
          if (accRes.success && Array.isArray(accRes.data) && accRes.data.length > 0) {
            const savingAcc = accRes.data.find((a: any) => a.bucket === "SAVING");
            if (savingAcc) {
              accId = savingAcc.id;
            }
          }
        }
        const payload = {
          accountId: accId,
          direction: (action.direction || "CREDIT") as any,
          amount: parseCleanFloat(action.amount),
          refType: sanitizeInput(action.refType, "Transfer"),
          note: sanitizeInput(action.note, "Mutasi tabungan otomatis via Finter AI"),
          currency: "IDR",
        };

        const res = await createLedgerAction(payload);
        if (res.success) {
          showToast(`Mutasi tabungan ${formatAmount(payload.amount, payload.accountId)} dicatat sukses!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal mencatatkan mutasi tabungan.", "error");
        }
      } else if (action.type === "create-enum" && action.category && action.value) {
        const allowedCategories = ["income_source", "income_type", "outcome_category", "outcome_subcategory"];
        if (!allowedCategories.includes(action.category)) {
          showToast(`Kategori enum tidak valid/diizinkan!`, "error");
          continue;
        }

        const res = await createEnumAction({
          category: action.category,
          value: action.value.replace(/<[^>]*>?/gm, '').trim()
        });

        if (res.success) {
          showToast(`Opsi "${action.value}" berhasil ditambahkan!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast(res.error || "Gagal menambahkan opsi enum.", "error");
        }
      } else if (action.type === "refresh-exchange-rates") {
        showToast("Sedang memperbarui nilai kurs dari API global...", "info");
        const res = await refreshExchangeRatesAction();
        if (res.success) {
          showToast(`Nilai kurs berhasil diperbarui dari ${res.source || 'API Global'}!`, "success");
          window.dispatchEvent(new Event("refresh-data"));
        } else {
          showToast("Gagal memperbarui data kurs.", "error");
        }
      }
    } catch (err) {
      console.error("Gagal mengeksekusi aksi AI:", err);
    }
  }
}

function sanitizeInput(text: string | undefined, fallback: string): string {
  if (!text) return fallback;
  return text.replace(/<[^>]*>?/gm, '').substring(0, 255).trim() || fallback;
}
